import torch # Preserve differentiability through the explicitly verified native one-increment material update.
from v2_rebar_constitutive import symmetric_tensor,tensor_components,steel_response # Reuse the already native-verified full plastic metric semantics and endpoint stress closure.
def native_kinematic_increment(F,previous_state,yield_stress,young=200000.,poisson=.3): # Reproduce one accepted native static material increment for the exact two-point kinematic hardening table.
    identity=torch.eye(3,dtype=F.dtype,device=F.device);mu=young/(2.*(1.+poisson));root23=(2./3.)**.5;J=torch.linalg.det(F);J23=J.pow(2./3.);C=F.transpose(-1,-2)@F;Cinv=torch.linalg.inv(C);old_metric=symmetric_tensor(previous_state[...,10:16]);old_backstress=symmetric_tensor(previous_state[...,16:22]);old_peeq=previous_state[...,9];cp_inverse=identity-2.*old_metric # Native incplas.f starts from the previous accepted SDV state and current total deformation gradient.
    cp_bar=cp_inverse/J23[...,None,None];backstress_bar=old_backstress/J23[...,None,None];cp_trace=(C*cp_bar).sum((-2,-1))/3.;backstress_trace=(C*backstress_bar).sum((-2,-1))/3.;cp_deviator=cp_bar-cp_trace[...,None,None]*Cinv;backstress_deviator=backstress_bar-backstress_trace[...,None,None]*Cinv;trial_second_piola=mu*cp_deviator;xi=trial_second_piola-backstress_deviator;xi_norm=(F@xi@F.transpose(-1,-2)).square().sum((-2,-1)).clamp_min(1.e-30).sqrt() # Match native isochoric reference tensors, C-dependent trace removal and invariant Kirchhoff radius.
    trial_function=xi_norm-root23*J*yield_stress;active=trial_function>1.e-10;umbb=mu*cp_trace-backstress_trace;initial_slope=torch.where(old_peeq<.05,J*1500.,torch.zeros_like(J));cop_linear=trial_function/(umbb*(2.+(2./3.)*initial_slope/mu));crosses=(old_peeq+root23*cop_linear)>=.05;curve_change=J*1500.*(.05-old_peeq).clamp_min(0.);cop_plateau=(trial_function-umbb*root23*curve_change/mu)/(2.*umbb);cop=torch.where(active,torch.where(crosses,cop_plateau,cop_linear),torch.zeros_like(J)) # Solve the native scalar consistency equation exactly on each segment instead of assuming hardening continues beyond its final ordinate.
    peeq=old_peeq+root23*cop;dfkin=torch.where(peeq<.05,J*1500.,torch.zeros_like(J));c5=2.*umbb*cop/xi_norm;updated_backstress=old_backstress+(c5*dfkin*J23/(3.*mu))[...,None,None]*xi;updated_cp_inverse=cp_inverse-(c5*J23/mu)[...,None,None]*xi;updated_metric=(identity-updated_cp_inverse)/2.;response=steel_response(F,tensor_components(updated_metric),tensor_components(updated_backstress),young,poisson) # Preserve native additive Cp inverse update and its actual terminal-derivative backstress behavior, including a knot-crossing increment.
    state=previous_state.clone();state[...,3:9]=response['sigma_components'];state[...,9]=peeq;state[...,10:16]=tensor_components(updated_metric);state[...,16:22]=tensor_components(updated_backstress) # Update only physical steel stress and thirteen internal variables while leaving nonmaterial channels untouched.
    return {'state':state,'plastic_active':active,'consistency_parameter':cop,'trial_function':trial_function,'umbb':umbb,'det_F':J,'crossed_hardening_last_point':active&(old_peeq<.05)&(peeq>=.05),'scope':'Exactly one native static material increment with zero residual stress, E=200000MPa, nu=.3, and the two-point kinematic curve. A saved macroscopic stage may contain multiple such increments and must not be relabeled as one.'} # This local constitutive map is not a finite-element equilibrium solve or an inference of missing intermediate deformation gradients.
